USE CATALOG dcp_synth;
CREATE OR REPLACE VIEW `02_silver`.patient AS SELECT patient_id,display_name,CAST(birth_date AS DATE) birth_date,country,diabetes_type,therapy_profile,data_class,source_id,CAST(ingested_at AS TIMESTAMP) ingested_at,_run_id FROM `01_bronze`.patient_master WHERE patient_id IS NOT NULL;
CREATE OR REPLACE VIEW `02_silver`.glucose_readings AS SELECT reading_id,patient_id,CAST(event_time AS TIMESTAMP) event_time,CAST(glucose_mmol_l AS DOUBLE) glucose_mmol_l,trend,device_id,source_id,CAST(ingested_at AS TIMESTAMP) ingested_at,_run_id,CASE WHEN patient_id IS NOT NULL AND event_time IS NOT NULL AND CAST(glucose_mmol_l AS DOUBLE) BETWEEN 1.0 AND 35.0 THEN 'PASS' ELSE 'FAIL' END quality_status FROM `01_bronze`.cgm_readings;
CREATE OR REPLACE VIEW `02_silver`.consent_events AS SELECT *,ROW_NUMBER() OVER(PARTITION BY patient_id,consent_scope ORDER BY CAST(event_time AS TIMESTAMP) DESC,CAST(ingested_at AS TIMESTAMP) DESC,consent_event_id DESC) state_rank FROM `01_bronze`.consent_events;
